import json,math
from collections import Counter
from battery import Markov,SOURCE,PAD_ALPHABETS
from transforms import encode,decode,side_bits
from extract_works import PAIRS
from pathlib import Path

def events(block, kind, seed):
 encoded=encode(block,kind,seed); assert decode(encoded,kind)==block
 hist=[]; i=0
 while i<len(encoded):
  c=encoded[i]; assert c in SOURCE
  yield 's',hist,c
  i+=1
  if c!=' ' and kind in ('addB','matched_deterministic','matched_random'):
   p=encoded[i]; i+=1; yield 'p',hist+[(c,'')],p; hist=hist+[(c,p)]
  else: hist=hist+[(c,'')]

def key(hist,n):
 return tuple(hist[-n:]) if n else ()
class Aligned:
 def __init__(self,blocks,kind,n):
  self.kind,self.n=kind,n; self.ct={'s':{},'p':{}}; self.base={'s':Counter(),'p':Counter()}
  for i,b in enumerate(blocks):
   for typ,h,c in events(b,kind,40801+i):
    ctx=key(h,n); self.ct[typ].setdefault(ctx,Counter())[c]+=1;self.base[typ][c]+=1
 def bits(self,blocks):
  total=0
  for i,b in enumerate(blocks):
   for typ,h,c in events(b,self.kind,40802+i):
    alphabet=SOURCE if typ=='s' else PAD_ALPHABETS[self.kind]; base=self.base[typ]; row=self.ct[typ].get(key(h,self.n),Counter());
    p0=(base[c]+.5)/(base.total()+.5*len(alphabet));p=(row[c]+2*p0)/(row.total()+2);total-=math.log2(p)
  return total

def xblocks(bs,kind,seed):return [encode(b,kind,seed+i) for i,b in enumerate(bs)]
works=json.loads(Path('/tmp/voy-entropy/clean_works.json').read_text());out={}
for lang,pair in PAIRS.items():
 train=works[pair['train']][:64]; test=works[pair['evaluation']][:64]; a,b=train[:48],train[48:]
 val=Markov.fit(a,SOURCE).bits(b); n=min(range(9),key=lambda i:val[i]); base=Markov.fit(train,SOURCE).bits(test)[n]; N=sum(map(len,test));R={'order':n,'validation_bits_per_source':[round(x/sum(map(len,b)),6) for x in val], 'source_symbols':N,'source_inverse_bits':base,'source_rate':base/N,'transforms':{}}
 for kind in ('addB','matched_deterministic','matched_random'):
  tr=xblocks(train,kind,40801);te=xblocks(test,kind,40802); forward=Markov.fit(tr,SOURCE+PAD_ALPHABETS[kind]).bits(te)[n]; aligned=Aligned(train,kind,n).bits(test); side=sum(side_bits(t,kind) for t in test)
  R['transforms'][kind]={'forward_bits':forward,'forward_per_source':forward/N,'aligned_bits':aligned,'aligned_per_source':aligned/N,'inverse_bits':base+side,'inverse_per_source':(base+side)/N,'output_symbols':sum(map(len,te)), 'side_bits':side}

 # A known suffix rule bijectively relabels each source-space event as B,space
 # after a letter, and adds a forced final B. It carries exactly the source bits.
 for block in test:
  assert decode(encode(block,'suffix_B'),'suffix_B') == block
 suffix_train=xblocks(train,'suffix_B',40801);suffix_test=xblocks(test,'suffix_B',40802)
 suffix_forward=Markov.fit(suffix_train,SOURCE+'B').bits(suffix_test)[n]
 R['suffix_boundary_state']={'forward_bits':suffix_forward,'forward_per_source':suffix_forward/N,'bits':base,'per_source':base/N,'output_symbols':sum(len(encode(block,'suffix_B')) for block in test),'description':'At a source prediction after a letter, relabel probability of space as B then force space. At end of block emit B free. Else emit the source symbol. The decoder tracks whether previous source symbol was a letter; rule and block ends are shared.'}
 out[lang]=R
 print(lang,json.dumps(R),flush=True)
Path('/tmp/voy-entropy/matched-results.json').write_text(json.dumps(out,indent=2)+'\n')
